use axum::{body::Body,extract::Extension,http::{Request,StatusCode}};
use jsonwebtoken::{Algorithm,EncodingKey,Header,encode};
use novu_rust_api::operator_access_token::AccessTokenVerifier;
use serde_json::{Value,json};
use sha2::Digest;
use std::{sync::Arc,time::{SystemTime,UNIX_EPOCH},time::Duration};
use tokio_postgres::{Client,NoTls};
use tower::ServiceExt;
use uuid::Uuid;
async fn connect(url:&str)->Client{let(db,driver)=tokio_postgres::connect(url,NoTls).await.unwrap();tokio::spawn(driver);db}
fn request(token:&str,env:&str,workflow:&str,txn:&str)->Request<Body>{let context_id=if txn=="audit-failed" {"audit-failed"} else {"alpha"};Request::builder().method("POST").uri(format!("/v1/experimental/operator/events/trigger?environmentId={env}")).header("authorization",format!("Bearer {token}")).header("content-type","application/json").body(Body::from(json!({"name":workflow,"to":{"subscriberId":"alice","email":"alice@example.test"},"payload":{"name":"Alice"},"context":{"tenant":{"id":context_id,"data":{"plan":"gold"}}},"transactionId":txn}).to_string())).unwrap()}
#[tokio::test]
#[ignore="requires fully migrated disposable PostgreSQL and role creation"]
async fn operator_trigger_is_scoped_audited_and_atomic() {
 let url=std::env::var("TEST_DATABASE_URL").unwrap();let mut db=connect(&url).await;let role=format!("trigger_operator_{}",Uuid::new_v4().simple());
 db.batch_execute(&format!("CREATE ROLE {role} LOGIN; GRANT USAGE ON SCHEMA public TO {role}; GRANT SELECT ON public.novu_rust_workflows,public.novu_rust_environments TO {role}; GRANT EXECUTE ON FUNCTION public.novu_rust_operator_jwt_trigger_authorize(text,text,text,text,bigint,text),public.novu_rust_operator_jwt_trigger_enqueue(text,text,text,text,bigint,text,text,uuid,text,jsonb,jsonb) TO {role}")).await.unwrap();
 db.execute("INSERT INTO public.novu_rust_operator_jwt_api_logins SELECT rolname,oid FROM pg_roles WHERE rolname=$1",&[&role]).await.unwrap();
 db.batch_execute("INSERT INTO public.novu_rust_environments VALUES('operator-trigger-a','org'),('operator-trigger-b','org'); INSERT INTO public.novu_rust_operator_jwt_identities(issuer,subject,client_id,environment_id) VALUES('https://issuer.test','person','console','operator-trigger-a'),('https://issuer.test','person','console','operator-trigger-b'); INSERT INTO public.novu_rust_workflows(environment_id,identifier,active,has_steps,in_app_content) VALUES('operator-trigger-a','welcome',true,true,'Hello {{payload.name}}'),('operator-trigger-a','other',true,true,'Hello'),('operator-trigger-a','inactive',false,true,'Hello'),('operator-trigger-b','welcome',true,true,'Hello')").await.unwrap();
 let api_url=url.replacen("postgres://postgres@",&format!("postgres://{role}@"),1);let api=connect(&api_url).await;assert!(api.query("SELECT * FROM public.novu_queue_jobs",&[]).await.is_err());assert!(api.query("SELECT * FROM public.novu_rust_operator_jwt_trigger_execute_grants",&[]).await.is_err());
 let app=novu_rust_api::router(Arc::new(api)).layer(Extension(Arc::new(AccessTokenVerifier::new("https://issuer.test","swallow",&[("key",include_bytes!("fixtures/operator_jwt/test-only-public.pem"))]).unwrap())));
 let now=SystemTime::now().duration_since(UNIX_EPOCH).unwrap().as_secs();let mut h=Header::new(Algorithm::RS256);h.typ=Some("at+jwt".into());h.kid=Some("key".into());let token=encode(&h,&json!({"iss":"https://issuer.test","sub":"person","aud":"swallow","exp":now+120,"iat":now-1,"jti":"token","client_id":"console"}),&EncodingKey::from_rsa_pem(include_bytes!("fixtures/operator_jwt/test-only-private.pem")).unwrap()).unwrap();
 assert_eq!(app.clone().oneshot(request(&token,"operator-trigger-a","welcome","deny")).await.unwrap().status(),StatusCode::UNAUTHORIZED);
 db.batch_execute("INSERT INTO public.novu_rust_operator_jwt_trigger_execute_grants VALUES('https://issuer.test','person','console','operator-trigger-a','welcome'),('https://issuer.test','person','console','operator-trigger-a','inactive')").await.unwrap();
 assert_eq!(app.clone().oneshot(request(&token,"operator-trigger-a","other","deny-other")).await.unwrap().status(),StatusCode::UNAUTHORIZED);assert_eq!(app.clone().oneshot(request(&token,"operator-trigger-b","welcome","deny-env")).await.unwrap().status(),StatusCode::UNAUTHORIZED);
 let response=app.clone().oneshot(request(&token,"operator-trigger-a","welcome","accepted")).await.unwrap();assert_eq!(response.status(),StatusCode::CREATED);let value:Value=serde_json::from_slice(&axum::body::to_bytes(response.into_body(),16384).await.unwrap()).unwrap();assert_eq!(value["data"]["status"],"processed");
 assert_eq!(app.clone().oneshot(request(&token,"operator-trigger-a","welcome","accepted")).await.unwrap().status(),StatusCode::CREATED);
 let row=db.query_one("SELECT (SELECT count(*) FROM public.novu_queue_jobs WHERE environment_id='operator-trigger-a' AND payload->>'transactionId'='accepted'),(SELECT count(*) FROM public.novu_rust_operator_jwt_trigger_audit WHERE environment_id='operator-trigger-a' AND transaction_id='accepted')",&[]).await.unwrap();assert_eq!(row.get::<_,i64>(0),1);assert_eq!(row.get::<_,i64>(1),1);
 let hash=format!("{:x}",sha2::Sha256::digest(b"operator-fixture-key"));db.batch_execute("INSERT INTO public.novu_rust_users VALUES('operator-api-user')").await.unwrap();db.execute("INSERT INTO public.novu_rust_api_keys(key_hash,environment_id,user_id) VALUES($1,'operator-trigger-a','operator-api-user')",&[&hash]).await.unwrap();
 let ordinary=novu_rust_api::router(Arc::new(connect(&url).await));let ordinary_request=Request::builder().method("POST").uri("/v1/events/trigger").header("authorization","ApiKey operator-fixture-key").header("content-type","application/json").body(Body::from(json!({"name":"welcome","to":{"subscriberId":"alice","email":"alice@example.test"},"payload":{"name":"Alice"},"context":{"tenant":{"id":"alpha","data":{"plan":"gold"}}},"transactionId":"api-accepted"}).to_string())).unwrap();assert_eq!(ordinary.oneshot(ordinary_request).await.unwrap().status(),StatusCode::CREATED);
 let rows=db.query("SELECT payload-'transactionId' FROM public.novu_queue_jobs WHERE environment_id='operator-trigger-a' AND payload->>'transactionId' IN ('accepted','api-accepted') ORDER BY payload->>'transactionId'",&[]).await.unwrap();assert_eq!(rows.len(),2);assert_eq!(rows[0].get::<_,Value>(0),rows[1].get::<_,Value>(0));
 assert_eq!(db.query_one("SELECT data FROM public.novu_rust_contexts WHERE environment_id='operator-trigger-a' AND context_key='tenant:alpha'",&[]).await.unwrap().get::<_,Value>(0),json!({"plan":"gold"}));
 db.batch_execute(&format!("GRANT EXECUTE ON FUNCTION public.novu_rust_operator_token_revoked(bytea,bytea,bytea,bytea),public.novu_rust_operator_token_guard(bytea,bytea,bytea,bytea) TO {role}")).await.unwrap();
 let config=json!({"issuer":"https://issuer.test","audience":"swallow","keys":[{"kid":"key","pem":std::str::from_utf8(include_bytes!("fixtures/operator_jwt/test-only-public.pem")).unwrap()}],"check_token_revocation":true});let guarded=novu_rust_api::router(Arc::new(connect(&api_url).await)).layer(Extension(Arc::new(AccessTokenVerifier::from_json(&config.to_string()).unwrap())));
 let now=SystemTime::now().duration_since(UNIX_EPOCH).unwrap().as_secs();let guarded_token=encode(&h,&json!({"iss":"https://issuer.test","sub":"person","aud":"swallow","exp":now+120,"iat":now-1,"jti":"guarded-token","client_id":"console"}),&EncodingKey::from_rsa_pem(include_bytes!("fixtures/operator_jwt/test-only-private.pem")).unwrap()).unwrap();
 assert_eq!(guarded.clone().oneshot(request(&guarded_token,"operator-trigger-a","welcome","guarded-before")).await.unwrap().status(),StatusCode::CREATED);
 db.execute("INSERT INTO public.novu_rust_operator_token_revocations(issuer_hash,subject_hash,client_hash,token_id_hash,reason) VALUES(sha256(convert_to('https://issuer.test','UTF8')),sha256(convert_to('person','UTF8')),sha256(convert_to('console','UTF8')),sha256(convert_to('guarded-token','UTF8')),'fixture')",&[]).await.unwrap();
 assert_eq!(guarded.oneshot(request(&guarded_token,"operator-trigger-a","welcome","guarded-after")).await.unwrap().status(),StatusCode::UNAUTHORIZED);assert_eq!(db.query_one("SELECT count(*) FROM public.novu_rust_trigger_transactions WHERE environment_id='operator-trigger-a' AND transaction_id='guarded-after'",&[]).await.unwrap().get::<_,i64>(0),0);
 let response=app.clone().oneshot(request(&token,"operator-trigger-a","inactive","inactive")).await.unwrap();assert_eq!(response.status(),StatusCode::CREATED);let value:Value=serde_json::from_slice(&axum::body::to_bytes(response.into_body(),16384).await.unwrap()).unwrap();assert_eq!(value["data"]["status"],"trigger_not_active");
 db.batch_execute("CREATE FUNCTION public.test_operator_trigger_audit_failure() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'fixture'; END $$; CREATE TRIGGER test_operator_trigger_audit_failure BEFORE INSERT ON public.novu_rust_operator_jwt_trigger_audit FOR EACH ROW EXECUTE FUNCTION public.test_operator_trigger_audit_failure()").await.unwrap();
 assert_eq!(app.clone().oneshot(request(&token,"operator-trigger-a","welcome","audit-failed")).await.unwrap().status(),StatusCode::INTERNAL_SERVER_ERROR);db.batch_execute("DROP TRIGGER test_operator_trigger_audit_failure ON public.novu_rust_operator_jwt_trigger_audit; DROP FUNCTION public.test_operator_trigger_audit_failure()").await.unwrap();
 let row=db.query_one("SELECT (SELECT count(*) FROM public.novu_rust_trigger_transactions WHERE environment_id='operator-trigger-a' AND transaction_id='audit-failed'),(SELECT count(*) FROM public.novu_queue_jobs WHERE environment_id='operator-trigger-a' AND payload->>'transactionId'='audit-failed'),(SELECT count(*) FROM public.novu_rust_contexts WHERE environment_id='operator-trigger-a' AND context_key='tenant:audit-failed')",&[]).await.unwrap();assert_eq!(row.get::<_,i64>(0),0);assert_eq!(row.get::<_,i64>(1),0);assert_eq!(row.get::<_,i64>(2),0);
 db.batch_execute("CREATE FUNCTION public.test_operator_trigger_pause() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.transaction_id='expiry' THEN PERFORM pg_advisory_xact_lock(874215); END IF; RETURN NEW; END $$; CREATE TRIGGER test_operator_trigger_pause BEFORE INSERT ON public.novu_rust_trigger_transactions FOR EACH ROW EXECUTE FUNCTION public.test_operator_trigger_pause()").await.unwrap();
 let now=SystemTime::now().duration_since(UNIX_EPOCH).unwrap().as_secs();let short=encode(&h,&json!({"iss":"https://issuer.test","sub":"person","aud":"swallow","exp":now+3,"iat":now-1,"jti":"short","client_id":"console"}),&EncodingKey::from_rsa_pem(include_bytes!("fixtures/operator_jwt/test-only-private.pem")).unwrap()).unwrap();
 let blocker=db.transaction().await.unwrap();blocker.query_one("SELECT pg_advisory_xact_lock(874215)",&[]).await.unwrap();let observer=connect(&url).await;let pending=tokio::spawn(app.clone().oneshot(request(&short,"operator-trigger-a","welcome","expiry")));let mut waiting=false;for _ in 0..100{waiting=observer.query_one("SELECT EXISTS(SELECT 1 FROM pg_stat_activity WHERE wait_event='advisory' AND query LIKE '%novu_rust_operator_jwt_trigger_enqueue%')",&[]).await.unwrap().get(0);if waiting{break}tokio::time::sleep(Duration::from_millis(20)).await;}assert!(waiting);tokio::time::sleep(Duration::from_secs(4)).await;blocker.rollback().await.unwrap();assert_eq!(pending.await.unwrap().unwrap().status(),StatusCode::UNAUTHORIZED);
 let row=db.query_one("SELECT (SELECT count(*) FROM public.novu_rust_trigger_transactions WHERE environment_id='operator-trigger-a' AND transaction_id='expiry'),(SELECT count(*) FROM public.novu_rust_operator_jwt_trigger_audit WHERE environment_id='operator-trigger-a' AND transaction_id='expiry')",&[]).await.unwrap();assert_eq!(row.get::<_,i64>(0),0);assert_eq!(row.get::<_,i64>(1),0);db.batch_execute("DROP TRIGGER test_operator_trigger_pause ON public.novu_rust_trigger_transactions; DROP FUNCTION public.test_operator_trigger_pause()").await.unwrap();
 let tx=db.transaction().await.unwrap();tx.execute("DELETE FROM public.novu_rust_operator_jwt_trigger_execute_grants WHERE environment_id='operator-trigger-a' AND workflow_identifier='welcome'",&[]).await.unwrap();
 let pending=tokio::spawn(app.clone().oneshot(request(&token,"operator-trigger-a","welcome","revoked")));tokio::time::sleep(Duration::from_millis(150)).await;assert!(!pending.is_finished());tx.commit().await.unwrap();assert_eq!(pending.await.unwrap().unwrap().status(),StatusCode::UNAUTHORIZED);
 let count:i64=db.query_one("SELECT count(*) FROM public.novu_rust_trigger_transactions WHERE environment_id='operator-trigger-a' AND transaction_id='revoked'",&[]).await.unwrap().get(0);assert_eq!(count,0);
}
